package com.ecole.gestion_scolaire.hr.controller; import com.ecole.gestion_scolaire.hr.dto.HrDashboardResponse; import com.ecole.gestion_scolaire.hr.service.HrDashboardService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/hr/dashboard") public class HrDashboardController { private final HrDashboardService service; public HrDashboardController(HrDashboardService s){service=s;} @GetMapping @PreAuthorize("hasAuthority('PERSONNEL_DASHBOARD')") public HrDashboardResponse dashboard(@RequestParam(required=false) Long schoolYearId){return service.dashboard(schoolYearId);} }